-- English Physics Chapter 3: Alternating Current (45 supplied MCQs).
-- Keep question order, answer indices, and stable IDs in sync with
-- src/data/physicsChapter3EnglishMcqs.json, the frontend fallback.
WITH seed (id, section, question, choices, answer_index, sort_order) AS (
  VALUES
  ('7b339c73-0095-443c-9ae5-000000000001'::uuid, 'Introduction and AC Basics', 'Direct current (DC) is the current that:', '["Alternates periodically with time","Flows in one direction and is generated by batteries","Reverses several times per second","Is generated by giant generators in power stations"]'::jsonb, 1, 1),
  ('7b339c73-0095-443c-9ae5-000000000002'::uuid, 'Introduction and AC Basics', 'Alternating current is preferred in electrical circuits because:', '["It is easy to transport over long distances with minimum energy loss","It cannot be stepped up or down","It does not follow Faraday''s law","It is produced only by batteries"]'::jsonb, 0, 2),
  ('7b339c73-0095-443c-9ae5-000000000003'::uuid, 'Introduction and AC Basics', 'Electric power is transmitted at high voltage and low current using step-up transformers in order to:', '["Increase the current in the wires","Increase the resistance of the wires","Reduce the power loss (P = I²R) in the transfer wires","Increase the frequency"]'::jsonb, 2, 3),
  ('7b339c73-0095-443c-9ae5-000000000004'::uuid, 'Introduction and AC Basics', 'What is used at consumption sites in cities to reduce the voltage and raise the current?', '["Step-up transformers","Step-down transformers","Batteries","Capacitors"]'::jsonb, 1, 4),
  ('7b339c73-0095-443c-9ae5-000000000005'::uuid, 'Introduction and AC Basics', 'A coil rotating with uniform angular velocity inside a uniform magnetic field produces:', '["A constant direct voltage","A sinusoidal alternating induced voltage","Zero voltage","A square-wave voltage"]'::jsonb, 1, 5),
  ('7b339c73-0095-443c-9ae5-000000000006'::uuid, 'Introduction and AC Basics', 'The maximum induced voltage (V = Vm) is obtained when the phase angle ωt equals:', '["0","π","2π","π/2"]'::jsonb, 3, 6),
  ('7b339c73-0095-443c-9ae5-000000000007'::uuid, 'Pure Resistor and Effective Value', 'In an AC circuit with a pure resistor, the phase difference between voltage and current is:', '["0","90°","180°","45°"]'::jsonb, 0, 7),
  ('7b339c73-0095-443c-9ae5-000000000008'::uuid, 'Pure Resistor and Effective Value', 'An AC circuit contains a single load in which current and voltage are in one phase. The load is:', '["A pure inductor","A pure capacitor","A pure resistor","None of the above"]'::jsonb, 2, 8),
  ('7b339c73-0095-443c-9ae5-000000000009'::uuid, 'Pure Resistor and Effective Value', 'The instantaneous power curve in a pure resistor circuit is always positive because:', '["Voltage and current are in the same phase, so their product is always positive","The phase difference is 90°","The circuit has no resistance","The frequency is zero"]'::jsonb, 0, 9),
  ('7b339c73-0095-443c-9ae5-000000000010'::uuid, 'Pure Resistor and Effective Value', 'The average power in a pure resistor circuit equals:', '["Im·Vm","Im·Vm / 2","Zero","2·Im·Vm"]'::jsonb, 1, 10),
  ('7b339c73-0095-443c-9ae5-000000000011'::uuid, 'Pure Resistor and Effective Value', 'The relation between effective and maximum current is:', '["Ieff = 1.414 Im","Ieff = 0.5 Im","Ieff = 0.707 Im","Ieff = 1.5 Im"]'::jsonb, 2, 11),
  ('7b339c73-0095-443c-9ae5-000000000012'::uuid, 'Pure Resistor and Effective Value', 'The effective value of an alternating current is:', '["Its maximum value","The DC value that produces the same thermal effect in the same resistance and period","Its average value over one cycle","Its instantaneous value at t = 0"]'::jsonb, 1, 12),
  ('7b339c73-0095-443c-9ae5-000000000013'::uuid, 'Pure Resistor and Effective Value', 'Most AC ammeters and voltmeters measure:', '["The maximum value","The average value","The effective value","The instantaneous value"]'::jsonb, 2, 13),
  ('7b339c73-0095-443c-9ae5-000000000014'::uuid, 'Pure Resistor and Effective Value', 'The pointer of most DC ammeters reads zero when connected to an AC circuit because:', '["AC has no energy","They measure the maximum value","They measure the average value of AC, which is zero over a cycle","They are always broken"]'::jsonb, 2, 14),
  ('7b339c73-0095-443c-9ae5-000000000015'::uuid, 'Pure Inductor', 'In an AC circuit with a pure inductor, the voltage phase vector:', '["Precedes the current phase vector by 90°","Lags behind the current phase vector by 90°","Is in phase with the current","Is 180° out of phase with the current"]'::jsonb, 0, 15),
  ('7b339c73-0095-443c-9ae5-000000000016'::uuid, 'Pure Inductor', 'The inductive reactance is given by:', '["XL = 1/ωC","XL = ωL = 2πfL","XL = ωC","XL = L/ω"]'::jsonb, 1, 16),
  ('7b339c73-0095-443c-9ae5-000000000017'::uuid, 'Pure Inductor', 'The inductive reactance is directly proportional to:', '["The self-inductance coefficient L and the frequency f","The reciprocal of frequency","The capacitance C","The resistance R only"]'::jsonb, 0, 17),
  ('7b339c73-0095-443c-9ae5-000000000018'::uuid, 'Pure Inductor', 'At very high frequencies, a coil in an AC circuit acts as:', '["A closed switch","A pure resistance","An open switch","A capacitor"]'::jsonb, 2, 18),
  ('7b339c73-0095-443c-9ae5-000000000019'::uuid, 'Pure Inductor', 'A lamp is connected in series with a pure inductor and an AC source of constant voltage. When the frequency increases, the lamp glow:', '["Increases","Decreases","Stays unchanged","Flickers"]'::jsonb, 1, 19),
  ('7b339c73-0095-443c-9ae5-000000000020'::uuid, 'Pure Inductor', 'The average power in a pure inductor over a full cycle equals:', '["Im·Vm / 2","Im·Vm","Zero","Im·Vm / 4"]'::jsonb, 2, 20),
  ('7b339c73-0095-443c-9ae5-000000000021'::uuid, 'Pure Inductor', 'The frequency of the power curve in a pure inductor (or pure capacitor) circuit is:', '["Equal to the frequency of the voltage","Half the frequency of the voltage","Twice the frequency of the voltage","Four times the frequency of the voltage"]'::jsonb, 2, 21),
  ('7b339c73-0095-443c-9ae5-000000000022'::uuid, 'Pure Inductor', 'Inductive reactance is not an ohmic resistance and does not follow Joule''s law because:', '["It consumes all the power","It does not consume power (average power = 0)","It has no units","It is always zero"]'::jsonb, 1, 22),
  ('7b339c73-0095-443c-9ae5-000000000023'::uuid, 'Pure Capacitor', 'In an AC circuit with a pure capacitor, the current phase vector:', '["Precedes the voltage phase vector by 90°","Lags behind the voltage phase vector by 90°","Is in phase with the voltage","Is 180° out of phase with the voltage"]'::jsonb, 0, 23),
  ('7b339c73-0095-443c-9ae5-000000000024'::uuid, 'Pure Capacitor', 'The capacitive reactance is given by:', '["Xc = ωC","Xc = ωL","Xc = 1/ωC = 1/(2πfC)","Xc = C/ω"]'::jsonb, 2, 24),
  ('7b339c73-0095-443c-9ae5-000000000025'::uuid, 'Pure Capacitor', 'At very high frequencies, a capacitor in an AC circuit acts as:', '["A closed switch","An open switch","An inductor","A battery"]'::jsonb, 0, 25),
  ('7b339c73-0095-443c-9ae5-000000000026'::uuid, 'Pure Capacitor', 'At very low frequencies, a capacitor in an AC circuit acts as:', '["A closed switch","A resistor","An open switch","A coil"]'::jsonb, 2, 26),
  ('7b339c73-0095-443c-9ae5-000000000027'::uuid, 'Pure Capacitor', 'A lamp is connected in series with a pure capacitor and an AC source of constant voltage. When the frequency increases, the lamp glow:', '["Decreases","Stays unchanged","Turns off","Increases"]'::jsonb, 3, 27),
  ('7b339c73-0095-443c-9ae5-000000000028'::uuid, 'Pure Capacitor', 'An insulating material (dielectric) is inserted between the plates of a capacitor connected in series with a lamp. The effect is:', '["The lamp dims because the capacitance decreases","The capacitance increases, Xc decreases, the current increases, and the lamp glows brighter","The lamp is not affected","The capacitor becomes a resistor"]'::jsonb, 1, 28),
  ('7b339c73-0095-443c-9ae5-000000000029'::uuid, 'Pure Capacitor', 'In AC circuits, power is consumed (as heat) only in:', '["The pure inductor","The pure capacitor","The resistor","All three elements"]'::jsonb, 2, 29),
  ('7b339c73-0095-443c-9ae5-000000000030'::uuid, 'Power Factor and Impedance', 'The power factor is:', '["The ratio of real power to apparent power (Preal / Papp = cos φ)","The ratio of apparent power to real power","The product of real and apparent power","The difference between real and apparent power"]'::jsonb, 0, 30),
  ('7b339c73-0095-443c-9ae5-000000000031'::uuid, 'Power Factor and Impedance', 'The unit of apparent power is:', '["Watt","Volt-ampere (VA)","Ohm","Henry"]'::jsonb, 1, 31),
  ('7b339c73-0095-443c-9ae5-000000000032'::uuid, 'Power Factor and Impedance', 'The greatest value of the power factor is:', '["0","0.5","1","Infinity"]'::jsonb, 2, 32),
  ('7b339c73-0095-443c-9ae5-000000000033'::uuid, 'Power Factor and Impedance', 'The power factor of a circuit containing only a pure inductor is:', '["1","0","0.5","Infinity"]'::jsonb, 1, 33),
  ('7b339c73-0095-443c-9ae5-000000000034'::uuid, 'Power Factor and Impedance', 'The total impedance of a series R-L-C circuit is:', '["Z = R + XL + Xc","Z = √(R² + (XL − Xc)²)","Z = R + XL − Xc","Z = √(R² + XL² + Xc²)"]'::jsonb, 1, 34),
  ('7b339c73-0095-443c-9ae5-000000000035'::uuid, 'Resonance and Quality Factor', 'The condition of electrical resonance in a series R-L-C circuit is:', '["XL = Xc","XL > Xc","R = 0","XL = R"]'::jsonb, 0, 35),
  ('7b339c73-0095-443c-9ae5-000000000036'::uuid, 'Resonance and Quality Factor', 'The resonant frequency of an R-L-C circuit is:', '["2π√(LC)","1/√(LC)","1/(2π√(LC))","2π/√(LC)"]'::jsonb, 2, 36),
  ('7b339c73-0095-443c-9ae5-000000000037'::uuid, 'Resonance and Quality Factor', 'At resonance in a series R-L-C circuit:', '["Impedance is maximum","Current is minimum","Z = R, current is maximum, and power factor = 1","Power factor = 0"]'::jsonb, 2, 37),
  ('7b339c73-0095-443c-9ae5-000000000038'::uuid, 'Resonance and Quality Factor', 'In a series R-L-C circuit, when the source frequency is less than the resonant frequency, the circuit has:', '["Inductive properties because XL > Xc","Capacitive properties because Xc > XL","Pure ohmic properties because XL = Xc","A power factor of zero"]'::jsonb, 1, 38),
  ('7b339c73-0095-443c-9ae5-000000000039'::uuid, 'Resonance and Quality Factor', 'The quality factor of a series resonant circuit is given by:', '["Qf = (1/R)·√(C/L)","Qf = R·√(LC)","Qf = (1/R)·√(L/C)","Qf = R·√(C/L)"]'::jsonb, 2, 39),
  ('7b339c73-0095-443c-9ae5-000000000040'::uuid, 'Resonance and Quality Factor', 'When the resistance of a series resonant circuit increases:', '["Δω decreases and Qf increases","Δω increases and Qf decreases","Both Δω and Qf increase","Both Δω and Qf decrease"]'::jsonb, 1, 40),
  ('7b339c73-0095-443c-9ae5-000000000041'::uuid, 'Resonance and Quality Factor', 'The angular frequency width is given by:', '["Δω = L/R","Δω = R/L","Δω = R·L","Δω = 1/(R·L)"]'::jsonb, 1, 41),
  ('7b339c73-0095-443c-9ae5-000000000042'::uuid, 'Electromagnetic Oscillation', 'In an LC electromagnetic oscillation circuit, when the capacitor is fully charged (all energy stored in its electric field), the current is:', '["Maximum","Zero","Half the maximum","0.707 of the maximum"]'::jsonb, 1, 42),
  ('7b339c73-0095-443c-9ae5-000000000043'::uuid, 'Electromagnetic Oscillation', 'The amplitude of oscillation in an LC circuit fades with time because:', '["The capacitance is too small","The frequency is too high","The circuit contains resistance","The inductance is too large"]'::jsonb, 2, 43),
  ('7b339c73-0095-443c-9ae5-000000000044'::uuid, 'Electromagnetic Oscillation', 'In a series R-L-C circuit, if the source angular frequency is doubled:', '["R, XL and Xc all double","XL doubles, Xc is halved, and R stays constant","XL is halved, Xc doubles, and R stays constant","None of them changes"]'::jsonb, 1, 44),
  ('7b339c73-0095-443c-9ae5-000000000045'::uuid, 'Electromagnetic Oscillation', 'The voltage across one reactance in a series R-L-C circuit may be greater than the total voltage because:', '["Voltages add as phasors, and VL and Vc are 180° out of phase","Voltages add algebraically","The resistance is zero","The frequency is infinite"]'::jsonb, 0, 45)
)
INSERT INTO public.mcq_banks (id, subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order)
SELECT s.id, 'physics', 3, 'Alternating Current', s.section, 'en', s.question, s.choices, s.answer_index,
       'Chapter 3 – Alternating Current: MCQ Test', s.sort_order
FROM seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.mcq_banks b
  WHERE b.subject = 'physics' AND b.chapter = 3 AND b.language = 'en' AND b.question = s.question
)
ON CONFLICT (id) DO NOTHING;